CREATE TABLE sucursales (id_sucursal INTEGER PRIMARY KEY, nombre VARCHAR NOT NULL, ciudad VARCHAR NOT NULL); INSERT INTO sucursales VALUES (1, 'Centro', 'Bogotá'), (2, 'Norte', 'Bogotá'), (3, 'Chapinero', 'Bogotá'), (4, 'Kennedy', 'Bogotá'); CREATE TABLE productos (id_producto INTEGER PRIMARY KEY, nombre VARCHAR NOT NULL, categoria VARCHAR NOT NULL, precio DECIMAL(5,2) NOT NULL); INSERT INTO productos VALUES (1, 'Café americano', 'Bebidas calientes', 3.50), (2, 'Capuchino', 'Bebidas calientes', 4.20), (3, 'Té verde', 'Bebidas calientes', 3.00), (4, 'Jugo de naranja', 'Bebidas frías', 3.80), (5, 'Croissant', 'Panadería', 2.50), (6, 'Muffin de arándanos', 'Panadería', 2.80); CREATE TABLE ventas (id_venta INTEGER PRIMARY KEY, id_sucursal INTEGER NOT NULL REFERENCES sucursales(id_sucursal), id_producto INTEGER NOT NULL REFERENCES productos(id_producto), fecha DATE NOT NULL, cantidad INTEGER NOT NULL); INSERT INTO ventas VALUES (1, 1, 1, '2026-01-05', 2), (2, 1, 2, '2026-01-05', 1), (3, 1, 5, '2026-01-06', 3), (4, 1, 1, '2026-01-07', 1), (5, 2, 2, '2026-01-05', 2), (6, 2, 4, '2026-01-06', 1), (7, 2, 6, '2026-01-07', 2), (8, 2, 1, '2026-01-08', 1), (9, 3, 3, '2026-01-05', 1), (10, 3, 2, '2026-01-06', 3), (11, 3, 5, '2026-01-07', 2), (12, 3, 1, '2026-01-08', 1), (13, 4, 4, '2026-01-05', 2), (14, 4, 6, '2026-01-06', 1), (15, 4, 2, '2026-01-07', 1), (16, 4, 1, '2026-01-08', 2);
